using System.Collections.Generic;using UnityEngine;

// Starts before fighter Awake; contact batch runs after both fighter FixedUpdates.
[DefaultExecutionOrder(-500)]public sealed class CombatTestV01:MonoBehaviour {
 public CombatV01Profile profile;public TrainingFighter player,opponent;public string Status{get;private set;}="";public CombatV01Result? Last{get;private set;}
 sealed class Contact{public TrainingFighter from,to;public TrainingHurtbox part;public double a,d;public bool guard,fd;public int jg;public float damage,chip,push;public long age;}
 float? chosenTG0,chosenTG1;
 readonly List<Contact> pending=new List<Contact>();readonly List<Object> owned=new List<Object>();TrainingMoveSet runtimeMoves;TrainingHurtboxProfile runtimeHurt;double tg0,tg1;
 void Awake(){if(profile==null||!profile.Valid){enabled=false;Status="Invalid v0.1 profile";return;}if(player==null)player=GetComponent<TrainingFighter>();if(opponent==null)opponent=player.opponent;runtimeMoves=Instantiate(profile.moves);runtimeHurt=Instantiate(profile.hurtboxes);owned.Add(runtimeMoves);owned.Add(runtimeHurt);foreach(var actor in new[]{player,opponent}){actor.CombatV01=this;actor.Tension.SuppressGains=true;actor.moveSet=runtimeMoves;actor.hurtboxProfile=runtimeHurt;var definition=Instantiate(actor.definition);owned.Add(definition);definition.maxHealth=profile.hp;definition.defenseLevel=definition.guardDefenseLevel=profile.hurtboxes.regions[0].midDefense;actor.definition=definition;var tuning=actor.GetComponent<ApprovedLocomotionTuning>();if(tuning!=null)tuning.enableDeveloperTuning=false;}var batch=gameObject.AddComponent<CombatV01ContactBatch>();batch.owner=this;}
 void Start(){ResetTest();}
 public float TGFor(TrainingFighter actor)=>actor==player?chosenTG0??profile.playerTG:chosenTG1??profile.opponentTG;
 [ContextMenu("Reset v0.1 HP / authored TG") ]public void ResetTest(){if(!profile.Validate(out var error)){Status="Rejected reset: "+error;return;}pending.Clear();Last=null;if(player!=null){player.definition.maxHealth=opponent.definition.maxHealth=profile.hp;player.ResetTraining();}Status="Reset HP and selected TG. TG earning / FD consumption disabled; TRC retains cost.";}
 public void ApplyPreset(int preset){chosenTG0=preset==4?200:(preset==5||preset==6)?100:0;chosenTG1=preset==1?100:preset==2?200:preset==4?80:preset==6?100:0;float d=(preset==3||preset==4)?180:100;foreach(var region in runtimeHurt.regions)region.highDefense=region.midDefense=region.lowDefense=d;ResetTest();Status="Runtime preset "+preset+"; Ctrl uses training settings; developer reset restores preset; source SO unchanged";}
 public void ApplyAuthored(){if(!profile.Validate(out var error)){Status="Rejected authored data: "+error;return;}chosenTG0=chosenTG1=null;JsonUtility.FromJsonOverwrite(JsonUtility.ToJson(profile.moves),runtimeMoves);JsonUtility.FromJsonOverwrite(JsonUtility.ToJson(profile.hurtboxes),runtimeHurt);player.RebuildHurtboxes();opponent.RebuildHurtboxes();ResetTest();}
 public void QueueOpponentP(TrainingCommand command){if(command==TrainingCommand.Light||command==TrainingCommand.Medium||command==TrainingCommand.Heavy)opponent.InputBuffer.Push(command,opponent.LockKind);}
 public void SetRuntimeTG(float first,float second){player.Tension.SetTestGauge(first);opponent.Tension.SetTestGauge(second);}
 public void Queue(TrainingFighter from,TrainingHurtbox part){var move=from.CurrentMove;pending.Add(new Contact{from=from,to=part.Fighter,part=part,a=from.AttackLevelFor(part),d=part.Fighter.V01Defense(part,from.CurrentAttackClass),guard=part.Fighter.V01MatchingGuard(from.CurrentAttackClass),fd=part.Fighter.FdActive,jg=part.Fighter.V01JGReduction,age=part.Fighter.V01JGAge,damage=move==null?1:move.combatDamageMultiplier,chip=move==null?.1f:move.combatChipMultiplier,push=move==null?.001f:move.combatPushbackScale});}
 public void ResolveBatch(){foreach(var actor in new[]{player,opponent})if(actor.V01CanContact){foreach(var part in actor.SelectHurtboxContacts(TrainingPhysicsQueries2D.OverlapBox(actor.HitboxCenter,actor.HitboxHalfSize),actor.CurrentAttackClass)){if(part.Fighter.Health<=0)continue;Queue(actor,part);actor.V01Connect();break;}}if(pending.Count==0)return;tg0=player.Tension.Gauge;tg1=opponent.Tension.Gauge;pending.Sort((a,b)=>(a.from==player?0:1).CompareTo(b.from==player?0:1));foreach(var c in pending){var r=CombatV01Formula.Resolve(c.a,c.d,c.from==player?tg0:tg1,c.to==player?tg0:tg1,c.guard,c.fd,c.jg,c.damage,c.chip,c.push,profile);r.jgAge=c.age;c.to.V01Receive(r,c.from,c.part);Last=r;Status="Part "+c.part.StableId+" | "+r.outcome+(r.fd?" FD":"")+(c.to.Health<=0?" KO":"");}pending.Clear();}
 void OnGUI(){if(!enabled||profile==null)return;var hud=FindAnyObjectByType<TrainingOverlay>();if(hud!=null&&(hud.OptionVisible||hud.MatchDisplay!=null))return;var text="COMBAT TEST v0.1 | Editor tuning | J/K/L P; A/D, W, S; back+U or back+J+M = FD\nHP "+player.Health.ToString("0.##")+" / "+opponent.Health.ToString("0.##")+" | TG "+player.Tension.Gauge.ToString("0.##")+" / "+opponent.Tension.Gauge.ToString("0.##")+" | Ctrl reset configured HP/TG | TRC ; retains cost\n"+Status;
 if(Last.HasValue){var r=Last.Value;text+=$"\nA {r.A:0.###} D {r.D:0.###} H {r.H:0.###} B {r.B:0.###} | TG snapshot {r.attackTG:0.##}/{r.defenseTG:0.##}\nJG age {r.jgAge}F reduction {r.jgReduction} | stop {r.hitstopFrames}F stun {r.stunFrames}F | damage {r.damage:0.###}\nself push {r.selfPush:0.####}m / attacker {r.attackerPush:0.####}m | surplus {r.surplus:0.###}F (bonus deferred)";}
 GUI.Box(new Rect(10,140,Mathf.Min(Screen.width-20,1000),145),text);}
 void OnDestroy(){foreach(var item in owned)if(item!=null)Destroy(item);}
}
